    """The porter's own probe output (model, leakage check, ...) for a probe sha, not a
    later reuse's copy, and where it was made (ledger, line, run)."""
    import sqlite3

    for ledger in ledgers:
        conn = sqlite3.connect(f"file:{ledger}?mode=ro", uri=True)
